{
  "name": "loss_rank_gap_tanh_advantage",
  "intuition": "Use a ranking loss paradigm based on the hyperbolic tangent of the rank gap scaled by the advantage difference to enforce preference ordering, providing a smooth bounded penalty that amplifies large disagreements in rank and advantage.",
  "pseudocode": "loss = mean(weight * relu(tanh(scale * rank_gap) * (advantage_l - advantage_w)))",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "relu_nonnegative"
  },
  "operators_used": ["tanh", "mean", "relu", "mul"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "rank_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    rank_gap = batch['rank_gap']\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    score = ops.tanh(ops.mul(scale, rank_gap))\n    diff = ops.sub(advantage_l, advantage_w)\n    loss_per_pair = ops.relu(ops.mul(score, diff))\n    if weight is not None:\n        loss_per_pair = ops.mul(loss_per_pair, weight)\n    return ops.mean(loss_per_pair)"
}

{
  "name": "loss_rank_gap_tanh_advantage_stable",
  "intuition": "Clamp the advantage difference within a reasonable range to prevent instability or overflow in the ReLU and tanh product, ensuring numerical stability while preserving the pairwise ranking semantics. Simplified the loss by removing redundant variable assignments and ensuring weight is non-negative and applied correctly.",
