    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    zeros = log_prob_w.new_zeros(log_prob_w.shape)\n    cost_gap = batch.get(\"cost_gap\", batch.get(\"cost_b\", zeros) - batch.get(\"cost_a\", zeros))\n    diff = ops.sub(log_prob_w, log_prob_l)\n    pref_score = ops.logsigmoid(diff)\n    loss = -ops.mean(ops.mul(pref_score, weight))\n    return loss"
}

{
  "name": "loss_exp_advantage_gap_weighted_sum",
  "intuition": "Transforms the aggregation from weighted mean to weighted sum to emphasize the cumulative effect of pairwise losses with exponential weighting by advantage gap, thus focusing more on the total weighted loss rather than average per pair.",
  "pseudocode": "rank_gap = batch['delta_rank']\nadv_gap = batch['advantage_gap']\nweight = batch.get('weight', 1)\nscore = exp(-alpha * rank_gap * adv_gap)\nloss = score * weight\nreturn sum(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_soft_ranking",
    "signal_family": "advantage_gap",
    "link_family": "exponential",
    "agg_family": "weighted_sum",
    "constraint_family": "none"
  },
  "operators_used": ["exp", "sum", "mul"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_rank", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    rank_gap = batch['delta_rank']\n    adv_gap = batch['advantage_gap']\n    weight = batch.get('weight', ops.ones_like(rank_gap))\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    score = ops.exp(-alpha * rank_gap * adv_gap)\n    weighted_score = score * weight\n    return ops.sum(weighted_score)"
}

{
  "name": "pairwise_sum_clamped_advantage_gap",
  "intuition": "This loss computes a pairwise preference using advantage_gap signals to encourage ordering consistency, applying a clamped sigmoid to stabilize the margin. The use of sum aggregation emphasizes the total penalty across pairs, suitable for descending optimization objectives. By weighting with explicit weights, it accounts for pair importance, and the clamping prevents extreme values from destabilizing training, leading to more robust preference learning.",
  "pseudocode": "loss = sum(-logsigmoid(clamp(alpha * scale * (log_prob_w - log_prob_l) - margin, -20, 20)) * weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "advantage_gap",
    "link_family": "logsigmoid",
    "agg_family": "sum",
    "constraint_family": "clamp_stabilized",
    "other_hparams": "alpha=1.0, scale=1.95"
  },
  "operators_used": ["logsigmoid", "clamp", "sum"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch['weight']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    x = alpha * scale * (lpw - lpl) - 0.1 * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    weighted_loss = loss * weight\n    total_loss = ops.sum(weighted_loss)\n    return total_loss"
}

{
  "name": "loss_inverse_ranking_exp_delta_regret_weighted_mean",
  "intuition": "A novel pairwise loss using an inverse exponential penalty on the regret difference, emphasizing harder mistakes with exponentially larger penalties, combined with a smooth sigmoid link for probability-like interpretation and aggregated as a weighted mean. This shifts the paradigm from margin or contrastive to an exponential regret-based probabilistic ranking paradigm, focusing on regret-driven preference learning.",
  "pseudocode": "regret_diff = delta_regret\nscaled = alpha * regret_diff\nloss = mean(weight * sigmoid(-scaled) * exp(scaled))",
  "hyperparams": {
    "paradigm_family": "pairwise_regret_probabilistic",
    "signal_family": "delta_regret",
    "link_family": "sigmoid_exp",
    "agg_family": "weighted_mean",
    "constraint_family": "none"
  },
  "operators_used": ["sigmoid", "exp", "mul", "neg", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_regret"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch['weight']\n    delta_regret = batch['delta_regret']\n    scaled = ops.mul(alpha, delta_regret)\n    loss_elements = ops.mul(ops.sigmoid(ops.neg(scaled)), ops.exp(scaled))\n    weighted_loss = ops.mul(loss_elements, weight)\n    return ops.mean(weighted_loss)"
}
